code.java:
class Solution {
    public int countPairs(int[] nums,int k){
        int answer=0;
        for(int i=0;i<nums.length;i++)for(int j=i+1;j<nums.length;j++)if(nums[i]==nums[j]&&i*j%k==0)answer++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countPairs(nums:IntArray,k:Int):Int{
        var answer=0;
        for(i in nums.indices)for(j in i+1 until nums.size)if(nums[i]==nums[j]&&i*j%k==0)answer++;
        return answer
    }
}

